parameters.jsCode:
const rows = $input.all();
const results = [];

for (const row of rows) {
  const d = row.json;

  const status = (d.status_reativacao || '').trim();
  if (status !== 'Pendente') continue;

  const nome = (d.nome_lead || '').trim();
  let telefone = (d.telefone || '').toString().trim();
  const id = d.id || '';

  if (!nome || !telefone) continue;

  telefone = telefone.replace(/\D/g, '');

  if (!telefone.startsWith('55')) {
    if (telefone.length === 11) {
      telefone = '55' + telefone;
    } else if (telefone.length === 10) {
      const ddd = telefone.substring(0, 2);
      const num = telefone.substring(2);
      telefone = '55' + ddd + '9' + num;
    }
  }

  const primeiroNome = nome.split(' ')[0];
  const leadIdCrm = (d.lead_id_cvcrm || '').toString();
  const templateNome = (d.mensagem_enviada || '').toString().trim();
  const observacao = (d.observacao_crm || '').toString().trim();
  const tipoCampanha = (d.tipo_campanha || 'reativacao').toString().trim();
  const idEmpreendimento = (d.empreendimento_id || '').toString().trim();

  results.push({ json: { nome, primeiroNome, telefone, id, leadIdCrm, templateNome, observacao, tipoCampanha, idEmpreendimento } });
}

if (results.length === 0) {
  return [{ json: { nenhum_pendente: true, total: 0 } }];
}

return results;

const d = $('Processar 1 por Vez').first().json;
const agoraObj = new Date();
const agora = agoraObj.toISOString();
const templateNome = (d.templateNome || '').trim();

// Verificação de horário (America/Sao_Paulo)
const horaAtualSP = new Date(agoraObj.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const horas = horaAtualSP.getHours();
const minutos = horaAtualSP.getMinutes();

// Trava de horário: Não enviar antes das 07:00 nem depois das 21:30
if (horas > 21 || (horas === 21 && minutos >= 30) || horas < 7) {
  return [{
    json: {
      templateValido: false,
      nome: d.nome,
      telefone: d.telefone,
      id: d.id,
      statusPlanilha: 'Pausado (Horário Excedido)'
    }
  }];
}

if (!templateNome) {
  return [{
    json: {
      templateValido: false,
      nome: d.nome,
      telefone: d.telefone,
      id: d.id,
      statusPlanilha: 'Erro - Template vazio'
    }
  }];
}

const primeiroNome = d.primeiroNome || d.nome.split(' ')[0];
const tipoCampanha = d.tipoCampanha || 'reativacao';
const idEmpreendimento = d.idEmpreendimento || '';

// Setup basic template message
const templateMessage = {
  name: templateNome,
  language: 'pt_BR',
  components: []
};

// Obter configuração dinâmica do template do Supabase
const templateResponse = $('Obter Template Supabase').first().json;
const templateData = Array.isArray(templateResponse) ? templateResponse[0] : templateResponse;

// Se o template estiver cadastrado e explicitamente disser que NÃO tem variáveis,
// temVariaveis será falso. Caso contrário (se não achar ou se estiver marcado true), assume true.
const temVariaveis = templateData ? (templateData.tem_variaveis !== false) : true;

if (temVariaveis) {
  templateMessage.components.push({
    type: 'body',
    parameters: [{ type: 'text', text: primeiroNome }]
  });
}

return [{
  json: {
    templateValido: true,
    nome: d.nome,
    primeiroNome,
    telefone: d.telefone,
    id: d.id,
    leadIdCrm: d.leadIdCrm || '',
    templateNome,
    tipoCampanha,
    observacao: d.observacao || '',
    idEmpreendimento,
    statusPlanilha: 'Enviado',
    evolutionPayload: {
      number: d.telefone,
      templateMessage: templateMessage
    },
    supabasePayload: {
      lead_id_cvcrm: d.leadIdCrm || d.telefone,
      telefone: d.telefone,
      nome_lead: d.nome,
      status_reativacao: 'Enviado',
      tipo_campanha: tipoCampanha,
      data_envio: agora,
      corretor_id_cvcrm: null,
      observacao_crm: d.observacao || null,
      empreendimento_id: idEmpreendimento || null,
      historico_mensagens: [{ remetente: 'TEMPLATE_WABA', template: templateNome, mensagem: 'Template: ' + templateNome, timestamp: agora }],
      mensagem_enviada: 'Template: ' + templateNome + (temVariaveis ? ' | Param: ' + primeiroNome : '')
    }
  }
}];

const original = $('Preparar Payload WhatsApp').first().json;
const payload = JSON.parse(JSON.stringify(original.evolutionPayload));
const tinhaVariavel = payload.templateMessage.components.length > 0;
const novoTemVariaveis = !tinhaVariavel;

// Inverte a hipótese original: se mandamos com variável e a Meta recusou por parâmetro,
// tentamos de novo sem variável (e vice-versa) — sem precisar de cadastro manual prévio.
payload.templateMessage.components = novoTemVariaveis
  ? [{ type: 'body', parameters: [{ type: 'text', text: original.primeiroNome }] }]
  : [];

return [{ json: { evolutionPayload: payload, novoTemVariaveis } }];

const original = $('Preparar Payload WhatsApp').first().json;
let ajuste = null;
try {
  ajuste = $('Alternar Variavel e Preparar Reenvio').first().json;
} catch (e) {
  ajuste = null;
}

const resposta = $json;
const erro = resposta && resposta.error
  ? (resposta.error.message || resposta.error)
  : null;
const sucesso = !erro;

const temVariaveisFinal = ajuste
  ? ajuste.novoTemVariaveis
  : original.evolutionPayload.templateMessage.components.length > 0;

return [{
  json: {
    statusFinal: sucesso ? 'Enviado' : 'Erro no Disparo',
    mensagemFinal: sucesso
      ? 'Template: ' + original.templateNome + (temVariaveisFinal ? ' | Param: ' + original.primeiroNome : '')
      : 'Falha: ' + erro,
    historico: original.supabasePayload.historico_mensagens,
    // Só corrige o cadastro se essa foi uma tentativa de ajuste automático que deu certo —
    // assim o próximo disparo desse mesmo template já nasce correto, sem passo manual.
    deveCorrigirTemplate: !!ajuste && sucesso,
    templateNome: original.templateNome,
    novoTemVariaveis: temVariaveisFinal
  }
}];

